// ============================================
// VALIDATION INPUT - MCP Feedback Analyzer
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Required context fields ---
const userId = body.user_id || ctx.user_id;
const guildId = body.guild_id || ctx.guild_id;
const userRequest = body.user_request || ctx.user_request;

if (!userId) {
  errors.push('user_id requis');
}
if (!guildId) {
  errors.push('guild_id requis');
}
if (!userRequest) {
  errors.push('user_request requis');
}

// --- Webhook-specific parameters ---
const comment = body.comment || ctx.comment;
const feedbackType = body.feedback_type || ctx.feedback_type || 'unknown';
const language = body.language || ctx.language || 'fr';

if (!comment) {
  errors.push('comment requis');
}

// --- API Keys (passed by system, do not validate) ---
const openaiApiKey = body.openai_api_key || ctx.openai_api_key || body.plugin_context?.api_keys?.openai || '';

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  comment: comment,
  feedback_type: feedbackType,
  language: language,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  openaiApiKey: openaiApiKey,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

// ============================================
// PARSE RESPONSE - MCP Feedback Analyzer
// ============================================

const items = $input.all();
const prevData = $('Validate Input').first().json;

// --- Context fields for traceability ---
const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;
const startTime = prevData.startTime;

const results = items.map(item => {
  const latencyMs = Date.now() - startTime;

  // Check for API errors
  if (item.json.error) {
    return {
      json: {
        success: false,
        error: {
          code: item.json.error.code || 500,
          message: item.json.error.message || 'OpenAI API error',
          status: 'API_ERROR'
        },
        meta: {
          provider: 'openai',
          model: 'gpt-4o-mini',
          processing_time_ms: latencyMs
        },
        user_id: userId,
        guild_id: guildId,
        user_request: userRequest,
        _trace: {
          service_response: item.json.error,
          llm_response: null,
          provider: 'openai',
          model: 'gpt-4o-mini',
          latency_ms: latencyMs,
          user_id: userId,
          guild_id: guildId,
          user_request: userRequest
        }
      }
    };
  }

  try {
    const content = item.json.choices?.[0]?.message?.content || '{}';
    const analysis = JSON.parse(content);

    // Validate required fields
    const validCategories = ['length', 'accuracy', 'tone', 'speed', 'confirmation', 'detail', 'format', 'other'];
    if (!validCategories.includes(analysis.category)) {
      analysis.category = 'other';
    }

    // Ensure detected_problems is an array
    if (!Array.isArray(analysis.detected_problems)) {
      analysis.detected_problems = [];
    }

    // Ensure confidence is a number between 0 and 1
    if (typeof analysis.confidence !== 'number' || analysis.confidence < 0 || analysis.confidence > 1) {
      analysis.confidence = 0.5;
    }

    const analysisResult = {
      category: analysis.category,
      issue: analysis.issue || null,
      detected_problems: analysis.detected_problems,
      user_preference: analysis.user_preference || null,
      suggested_action: analysis.suggested_action || null,
      confidence: analysis.confidence
    };

    return {
      json: {
        success: true,
        analysis: analysisResult,
        meta: {
          provider: 'openai',
          model: 'gpt-4o-mini',
          processing_time_ms: latencyMs
        },
        user_id: userId,
        guild_id: guildId,
        user_request: userRequest,
        _trace: {
          service_response: analysisResult,
          llm_response: content,
          provider: 'openai',
          model: 'gpt-4o-mini',
          latency_ms: latencyMs,
          user_id: userId,
          guild_id: guildId,
          user_request: userRequest
        }
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: 'Failed to parse analysis response: ' + e.message,
          status: 'PARSE_ERROR'
        },
        meta: {
          provider: 'openai',
          model: 'gpt-4o-mini',
          processing_time_ms: latencyMs
        },
        user_id: userId,
        guild_id: guildId,
        user_request: userRequest,
        _trace: {
          service_response: { parse_error: e.message },
          llm_response: item.json.choices?.[0]?.message?.content,
          provider: 'openai',
          model: 'gpt-4o-mini',
          latency_ms: latencyMs,
          user_id: userId,
          guild_id: guildId,
          user_request: userRequest
        }
      }
    };
  }
});

return results;
